patch:
diff --git a/repro/no-var-use-before-declaration.js b/repro/no-var-use-before-declaration.js
new file mode 100644
index 0000000..88730df
--- /dev/null
+++ b/repro/no-var-use-before-declaration.js
@@ -0,0 +1,86 @@
+/**
+ * Check: `no-var` autofix must not turn working code into code that throws a
+ * ReferenceError (temporal dead zone) when the variable is read before its
+ * `var` declaration.
+ *
+ * Usage (from the repo root):
+ *   node repro/no-var-use-before-declaration.js
+ *   ESLINT_PATH=/path/to/node_modules/eslint node repro/no-var-use-before-declaration.js
+ *
+ * Exit codes: 0 = fixed output runs without a ReferenceError,
+ *             1 = fixed output throws a ReferenceError (the reported bug),
+ *             2 = something else went wrong (setup error, different failure).
+ */
+"use strict";
+
+const path = require("node:path");
+const vm = require("node:vm");
+
+const eslintPath = process.env.ESLINT_PATH
+	? path.resolve(process.env.ESLINT_PATH)
+	: path.resolve(__dirname, "..");
+const { Linter } = require(eslintPath);
+
+// Exact code and config from the report (playground: only `no-var: error`).
+const code = `export function a() {
+    console.log(o);
+    var o;
+    return o;
+}
+`;
+const config = [{ rules: { "no-var": ["error"] } }];
+
+const linter = new Linter();
+
+console.log(`ESLint ${Linter.version} (${eslintPath})`);
+
+// The original code is valid: `var o` is hoisted, so `a()` returns undefined.
+function run(source) {
+	const logged = [];
+	const context = vm.createContext({
+		console: { log: (...args) => logged.push(args) },
+	});
+
+	// Evaluate as a script: drop `export` and expose `a` for the call.
+	vm.runInContext(source.replace(/^export /mu, ""), context);
+	return vm.runInContext("a()", context);
+}
+
+try {
+	run(code);
+} catch (error) {
+	console.error("Setup error: the original code should run fine:", error);
+	process.exit(2);
+}
+
+const messages = linter.verify(code, config, "a.js");
+
+if (
+	messages.length !== 1 ||
+	messages[0].ruleId !== "no-var" ||
+	messages[0].line !== 3
+) {
+	console.error("Setup error: expected exactly one no-var report on line 3");
+	console.error(messages);
+	process.exit(2);
+}
+
+const { output } = linter.verifyAndFix(code, config, "a.js");
+
+console.log("--- output after autofix ---");
+console.log(output);
+console.log("----------------------------");
+
+try {
+	run(output);
+	console.log("PASS: fixed output runs without a ReferenceError");
+} catch (error) {
+	if (error && error.name === "ReferenceError") {
+		console.error(
+			`FAIL: fixed output throws ReferenceError: ${error.message}`,
+		);
+		process.exit(1);
+	}
+	console.error("Different failure (not the reported ReferenceError):", error);
+	process.exit(2);
+}
